-- Analytical View: Expression by Histology---- Purpose:-- Provide sample-level gene expression observations-- associated with the corresponding histological subtype.---- Grain:-- One row per sample and gene.---- Source:-- analytical.dim_sample-- analytical.fact_expressionCREATE OR REPLACE VIEW analytical.vw_expression_by_histology ASSELECT    s.sample_id,    s.histological_type,    f.gene_name AS gene,    f.expression_levelFROM analytical.dim_sample AS sINNER JOIN analytical.fact_expression AS f    ON s.sample_id = f.sample_id;